import datetime
import os
import re

from moler.device import DeviceFactory
from taf.rfrl.bts.connections.device_aliases import ws_du
from taf.rfrl.bts.devices.exceptions import AsirNotOnAir
from taf.rfrl.utilities.tl_config import load_moler_configuration_from_tl
from taf.rfrl.utilities.logger.custom_logger import log_warn_to_console
from taf.rfrl.utilities.robot.RobotKWRunner import run_as_robot_kw as convert_to_robot_kw


class GenericRunnerAsirEx(object):

    def _verify_rfc_cells_status(self):
        if self._rfc_cells is not None:
            try:
                rfc_cells_uid = [cell["uid"] for cell in self._rfc_cells]
                convert_to_robot_kw(self.asir.verify_units_state, bts_id=self.bts_id, units_uid=rfc_cells_uid)
            except AsirNotOnAir as e:
                self.custom_logger(log_warn_to_console, msg="RFCCELLS NOT ON-AIR: {}".format(repr(e)),
                                   log_hierarchy=3)
                convert_to_robot_kw(self._fail_iteration)

    def calculate_rfc_cells_kpi(self, results):
        rfc_kpi = {}
        kpi_names = [kpi_name for kpi_name in list(results) if kpi_name in self.kpi_rfc_names]
        try:
            rfc_timestamp = convert_to_robot_kw(self.get_rfccell_changing_state_timestamps_from_syslog)
            for rf_cell in list(rfc_timestamp):
                rfc_kpi[rf_cell] = {}
                start_time = sorted(rfc_timestamp[rf_cell]["Enabled_to_Disabled"])[0] \
                    if "Enabled_to_Disabled" in list(rfc_timestamp[rf_cell]) else None
                for kpi in kpi_names:
                    if start_time is None:
                        start_time = results[kpi][0]["start_point_timestamp"].replace(tzinfo=None)
                    kpi_val = (sorted(rfc_timestamp[rf_cell]["Degrade_to_Enabled"])[0] - start_time).total_seconds()
                    rfc_kpi[rf_cell][kpi] = kpi_val
            return rfc_kpi
        except Exception as e:
            self.custom_logger(log_warn_to_console, msg="FAILED TO CALCULATE RFC CELLS KPI: {}".format(repr(e)),
                               log_hierarchy=3)
            return None

    @load_moler_configuration_from_tl()
    def get_rfccell_changing_state_timestamps_from_syslog(self, path="/tmp/btslog2/"):
        device = convert_to_robot_kw(DeviceFactory.get_device, name=ws_du.format(self.bts_type, self.bts_id,
                                                                                 self.du_id))
        file_names = convert_to_robot_kw(self._get_files_names_from_location, path=path, file_regex=r"SYSLOG_.*")
        grep_regex = '-E "RFCCELL_R-[0-9]+ state from Enabled.*|RFCCELL_R-[0-9]+ state from .* to Enabled"'
        lines = []
        for file_name in file_names:
            lines.extend(convert_to_robot_kw(device.get_cmd, cmd_name='grep', cmd_params={"options": '{} {}{}'.
                                             format(grep_regex, path, file_name)})()["LINES"])
        return convert_to_robot_kw(self._get_timestamps_for_rfc_cells, lines=lines)

    @load_moler_configuration_from_tl()
    def _get_files_names_from_location(self, path, file_regex):
        device = convert_to_robot_kw(DeviceFactory.get_device, name=ws_du.format(self.bts_type, self.bts_id,
                                                                                 self.du_id))
        files = convert_to_robot_kw(device.get_cmd, cmd_name='ls',
                                    cmd_params={"path": os.path.join(path, 'SYSLOG_*')})()
        files_names = list(map(lambda x: x.split("/")[-1], files["files"].keys()))
        return files_names

    @staticmethod
    def _get_timestamps_for_rfc_cells(lines):
        rf_cells = {}
        pattern = re.compile(r"RFCCELL_R-[0-9]+")
        for line in lines:
            timestamp = datetime.datetime.strptime(re.search(r'<.*>', line)[0], "<%Y-%m-%dT%H:%M:%S.%fZ>")
            rf_cell_name = re.search(pattern, line)[0]
            states = re.search("state from (?P<FROM>.*) to (?P<TO>.*)", line)
            try:
                rf_cells[rf_cell_name]["{}_to_{}".format(states.group("FROM"), states.group("TO"))].append(timestamp)
                convert_to_robot_kw(log_warn_to_console,
                                    msg="MORE THAN ONE TIMESTAMP: {}, POSSIBLY CELL DOWN AFTER ON-AIR".
                                    format(rf_cells[rf_cell_name]), log_hierarchy=3)
            except KeyError:
                rf_cells[rf_cell_name] = {}
                rf_cells[rf_cell_name]["{}_to_{}".format(states.group("FROM"), states.group("TO"))] = [timestamp]
        return rf_cells

    def _get_asir_webem_alarms(self):
        convert_to_robot_kw(self.asir.get_active_asir_webem_alarms, bts_id=self.bts_id)
        convert_to_robot_kw(self.asir.get_historical_asir_webem_alarms, bts_id=self.bts_id)
